/* Anonymous counters only. Never sends note contents, IP, URL parameters or UA. */
(()=>{let visitor,session,qa=false,enabled=true,queue=Promise.resolve();try{const params=new URLSearchParams(location.search);if(params.has('qa'))sessionStorage.setItem('refinetaste-qa',params.get('qa')==='1'?'1':'0');qa=sessionStorage.getItem('refinetaste-qa')==='1';visitor=localStorage.getItem('refinetaste-visitor')||crypto.randomUUID();localStorage.setItem('refinetaste-visitor',visitor);session=sessionStorage.getItem('refinetaste-session')||crypto.randomUUID();sessionStorage.setItem('refinetaste-session',session)}catch{enabled=false}let run=null;window.RefineMetrics={send(kind,extra={}){if(!enabled||qa||!location.pathname.startsWith('/refinetaste/'))return;const body={id:crypto.randomUUID(),visitor,session,kind,run,...extra};queue=queue.then(()=>fetch('/refinetaste/api/collect',{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),keepalive:true})).catch(()=>{});},start(index){run=crypto.randomUUID();this.send('start',{start:index})}};window.RefineMetrics.send('view');})();
